        + checkedSermonExtractionIds('reference').length;
      elements.sermonExtractionStatus.dataset.kind = '';
      elements.sermonExtractionStatus.textContent = checkedCount > 0
        ? `${checkedCount} ${checkedCount === 1 ? 'suggestion is' : 'suggestions are'} checked. Checked Scripture citations will still need separate canonical review.`
        : 'No suggestions are checked. Nothing will change.';
      updateControlStates();
