        const reconciliation =
          state.communityPlanReview?.proposal?.reconciliation;
        const conflictId = input?.dataset?.communityPlanConflictId;
        const conflict = reconciliation?.conflicts?.find(candidate =>
          candidate.conflictId === conflictId);
        if (
          !input
          || input.type !== 'radio'
          || !input.checked
          || !conflict
          || ![
            conflict.local.choice,
            conflict.community.choice
          ].includes(input.value)
        ) {
          return;
        }
        state.communityPlanConflictChoices.set(conflictId, input.value);
        elements.communityPlanConfirmed.checked = false;
        updateCommunityPlanReconciliationControls();
